<?php require 'includes/bootstrap.php';require_admin();
$states=['Nueva','En proceso','Contactada','Cerrada'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=$_POST['action']??'';$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);
 if($action==='delete' && $id){$q=db()->prepare('DELETE FROM solicitudes WHERE id=?');$q->execute([$id]);flash('success','Solicitud eliminada.');redirect('admin.php');}
 if(in_array($action,['create','update'],true)){
    [$v,$errors]=validate_request($_POST);$state=(string)($_POST['estado']??'Nueva');
    if(!in_array($state,$states,true)) $errors[]='Estado inválido.';
    if($action==='update'&&!$id) $errors[]='Registro inválido.';
    if(!$errors){$v['estado']=$state;
      if($action==='create'){$q=db()->prepare('INSERT INTO solicitudes(nombre,email,empresa,telefono,servicio,mensaje,estado) VALUES (:nombre,:email,:empresa,:telefono,:servicio,:mensaje,:estado)');$q->execute($v);}
      else {$v['id']=$id;$q=db()->prepare('UPDATE solicitudes SET nombre=:nombre,email=:email,empresa=:empresa,telefono=:telefono,servicio=:servicio,mensaje=:mensaje,estado=:estado,updated_at=CURRENT_TIMESTAMP WHERE id=:id');$q->execute($v);}
      flash('success',$action==='create'?'Solicitud creada.':'Solicitud actualizada.');redirect('admin.php');
    }flash('danger',implode(' ', $errors));
 }
}
$editing=null;
if(isset($_GET['edit'])){$id=filter_var($_GET['edit'],FILTER_VALIDATE_INT);if($id){$q=db()->prepare('SELECT * FROM solicitudes WHERE id=?');$q->execute([$id]);$editing=$q->fetch()?:null;}}
$filter=(string)($_GET['estado']??'');if(!in_array($filter,$states,true))$filter='';
$q=db()->prepare('SELECT * FROM solicitudes WHERE (:filter = "" OR estado=:filter2) ORDER BY id DESC');$q->execute(['filter'=>$filter,'filter2'=>$filter]);$records=$q->fetchAll();
$total=(int)db()->query('SELECT COUNT(*) FROM solicitudes')->fetchColumn();
$pageTitle='Panel de solicitudes';require 'includes/header.php'; ?>
<section class="admin-area container-fluid site-width"><div class="d-flex flex-wrap justify-content-between gap-3 align-items-start mb-5"><div><span class="eyebrow">BYBELLA / DASHBOARD</span><h1>Solicitudes <em>recibidas.</em></h1><p>Gestiona clientes y cotizaciones desde SQLite. Total de registros: <strong><?=$total?></strong>.</p></div><form method="post" action="logout.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button class="outline-button" type="submit">Cerrar sesión ↗</button></form></div>
<div class="row g-4"><div class="col-xl-4"><section class="form-panel" id="editor"><span class="eyebrow"><?=$editing?'EDIT / #'.(int)$editing['id']:'CREATE / NEW'?></span><h2><?=$editing?'Editar solicitud':'Agregar solicitud'?></h2><form method="post" class="needs-validation" novalidate><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="<?=$editing?'update':'create'?>"><?php if($editing):?><input type="hidden" name="id" value="<?=(int)$editing['id']?>"><?php endif;?>
<?php foreach(['nombre'=>'Nombre','email'=>'Correo','empresa'=>'Empresa','telefono'=>'Teléfono'] as $key=>$label):?><label class="form-label" for="adm-<?=$key?>"><?=$label?> <?=in_array($key,['nombre','email'],true)?'*':''?></label><input class="form-control mb-3" id="adm-<?=$key?>" name="<?=$key?>" type="<?=$key==='email'?'email':'text'?>" maxlength="<?= $key==='nombre'?100:($key==='email'?150:($key==='empresa'?120:40)) ?>" <?=$key==='nombre'?'minlength="2"':''?> <?=in_array($key,['nombre','email'],true)?'required':''?> value="<?=e($editing[$key]??'')?>"><div class="invalid-feedback mb-2">Revisa este campo.</div><?php endforeach;?>
<label class="form-label" for="adm-servicio">Servicios *</label><select class="form-select mb-3" id="adm-servicio" name="servicio[]" multiple size="9" required><?php $adminSelected=selected_services($editing['servicio']??''); foreach(service_groups() as $groupName=>$options): ?><optgroup label="<?=e($groupName)?>"><?php foreach($options as $service):?><option value="<?=e($service)?>" <?=in_array($service,$adminSelected,true)?'selected':''?>><?=e($service)?></option><?php endforeach;?></optgroup><?php endforeach;?></select><p class="small text-muted">Puedes seleccionar varios servicios manteniendo Ctrl presionado.</p><label class="form-label" for="adm-mensaje">Mensaje *</label><textarea class="form-control mb-3" id="adm-mensaje" name="mensaje" minlength="10" maxlength="2500" rows="4" required><?=e($editing['mensaje']??'')?></textarea><label class="form-label" for="adm-estado">Estado</label><select class="form-select mb-4" id="adm-estado" name="estado"><?php foreach($states as $s):?><option value="<?=e($s)?>" <?=($editing['estado']??'Nueva')===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button type="submit" class="primary-button border-0 w-100 justify-content-between"><?=$editing?'Guardar cambios':'Crear solicitud'?> <span>↗</span></button><?php if($editing):?><a href="admin.php" class="d-block text-center mt-3">Cancelar edición</a><?php endif;?></form></section></div>
<div class="col-xl-8"><section class="admin-table-wrap"><div class="d-flex flex-wrap justify-content-between gap-2 align-items-center mb-4"><h2 class="m-0">Listado de solicitudes</h2><form method="get"><label class="visually-hidden" for="estado">Filtrar estado</label><select class="form-select" id="estado" name="estado" onchange="this.form.submit()"><option value="">Todos los estados</option><?php foreach($states as $s):?><option value="<?=e($s)?>" <?=$filter===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></form></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>ID / FECHA</th><th>CLIENTE</th><th>SERVICIO</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody><?php foreach($records as $r):?><tr><td><strong>#<?=(int)$r['id']?></strong><br><small><?=e($r['created_at'])?></small></td><td><strong><?=e($r['nombre'])?></strong><br><a href="mailto:<?=e($r['email'])?>"><?=e($r['email'])?></a><br><small><?=e($r['empresa'])?> <?=e($r['telefono'])?></small><details><summary>Ver mensaje</summary><p class="message-cell"><?=nl2br(e($r['mensaje']))?></p></details></td><td><?=e($r['servicio'])?></td><td><span class="status-pill"><?=e($r['estado'])?></span></td><td><div class="d-flex gap-2 align-items-center"><a class="table-action" href="admin.php?edit=<?=(int)$r['id']?>#editor">Editar</a><form method="post" class="delete-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button type="submit" class="table-action danger-action">Eliminar</button></form></div></td></tr><?php endforeach;?></tbody></table><?php if(!$records):?><p class="text-center py-5">Aún no hay solicitudes con este filtro.</p><?php endif;?></div></section></div></div></section>
<?php require 'includes/footer.php'; ?>
